{{#css:
.emoji-container{
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    padding: 16px;
}
.emoji-box{
    display: inline-block;
    cursor: pointer;
    position: relative;
    border-radius: 10%;
    overflow: hidden;
    width: calc(12.5% - 7px);
}
.emoji-img{
    width: 100%;
    background: #f8f4e9;
}
.divsort.emoji-box.hidden {
    display: none !important;
}
@media (max-width: 767px){
    .emoji-container{gap: 4px;}
    /* 手机端一行4个 */
    .emoji-box{width: calc(25% - 3px);}
}
@media (min-width: 768px) and (max-width: 991px){
    /* 平板端一行5个 */
    .emoji-box{width: calc(20% - 6.4px);}
}
/* 筛选项按钮文字缩小 */
.btn-default.cardSelectOption {
    font-size: 13px !important;
}
}}
